  async function adminWrite(req:FastifyRequest) {await admin(req);originGuard(req);if(typeof req.headers['x-csrf-token']!=='string'||!constantEqual(req.headers['x-csrf-token'],req.campusSession!.csrfToken))throw new AppError(403,'CSRF_REJECTED','页面凭证已失效，请刷新后重试。');}
