  app.post(prefix+'/internal/qq/transcribe',{bodyLimit:27*1024*1024,preHandler:bot,config:{rateLimit:{max:60,timeWindow:'1 minute'}},schema:{hide:true}},async req=>{let audio:{buffer:Buffer;mime:string;name:string}|null=null;for await(const part of req.parts()){if(part.type!=='file'||part.fieldname!=='audio')continue;if(audio)throw new AppError(400,'AUDIO_LIMIT','每次只能识别一条语音。');audio={buffer:await partBuffer(part,25*1024*1024),mime:part.mimetype||'application/octet-stream',name:safeName(part.filename)};}if(!audio)throw new AppError(400,'EMPTY_AUDIO','没有收到语音文件。');return {text:await models.transcribeAudio(audio.buffer,audio.mime,audio.name)};});
  app.post(prefix+'/internal/qq/materials',{bodyLimit:27*1024*1024,preHandler:bot,config:{rateLimit:{max:120,timeWindow:'1 minute'}},schema:{hide:true}},async(req,reply)=>{let metadataText='',file:{buffer:Buffer;mime:string;name:string}|null=null;for await(const part of req.parts()){if(part.type==='field'){if(part.fieldname==='metadata')metadataText=String(part.value);continue;}if(part.fieldname!=='file'||file)throw new AppError(400,'MATERIAL_FILE_LIMIT','每次只能接收一个资料文件。');file={buffer:await partBuffer(part,25*1024*1024),mime:part.mimetype||'application/octet-stream',name:safeName(part.filename)};}if(!file)throw new AppError(400,'EMPTY_UPLOAD','没有收到资料文件。');let metadata:{messageId:string;senderId:string;senderName?:string};try{metadata=JSON.parse(metadataText);}catch{throw new AppError(400,'INVALID_MATERIAL_METADATA','资料来源信息无效。');}if(typeof metadata.messageId!=='string'||!metadata.messageId||metadata.messageId.length>200||/[\p{Cc}\p{Cf}]/u.test(metadata.messageId)||!/^[A-Za-z0-9_-]{1,160}$/.test(metadata.senderId)||metadata.senderName&&metadata.senderName.length>80)throw new AppError(400,'INVALID_MATERIAL_METADATA','资料来源信息无效。');const extension=extname(file.name).toLowerCase(),allowed=new Set(['.pdf','.doc','.docx','.xls','.xlsx','.ppt','.pptx','.txt','.csv','.zip','.rar','.7z']);if(!allowed.has(extension))throw new AppError(400,'UNSUPPORTED_MATERIAL','资料仅支持 PPT、PDF、Word、Excel 及常用文档压缩包。');const sourceKey=materialSourceKey(metadata.messageId,file.name,file.buffer.length),existing=store.materialBySourceKey(sourceKey);if(existing){reply.code(200);return existing;}const categoryId=await materials.classify(file.name,store.listMaterialCategories()),storedName=saveBuffer(materialDirectory,file.buffer,extension.slice(1));try{const item=store.createMaterialItem({sourceKey,categoryId,name:file.name,storedName,mime:file.mime,size:file.buffer.length,senderId:metadata.senderId,senderName:metadata.senderName});reply.code(201);return item;}catch(error){rmSync(join(materialDirectory,storedName),{force:true});throw error;}});
  app.get<{Params:{id:string}}>(prefix+'/internal/qq/attachments/:id',{preHandler:bot,schema:{hide:true,params:idParams}},async(req,reply)=>{const faqFile=store.attachmentFile(req.params.id),ragFile=faqFile?undefined:store.ragFile(req.params.id),notificationFile=faqFile||ragFile?undefined:store.notificationAttachmentFile(req.params.id),file=faqFile||ragFile||notificationFile;if(!file)throw new AppError(404,'NOT_FOUND','附件不存在。');const path=faqFile?join(config.dataDir,'faq-attachments',faqFile.faq_id,faqFile.stored_name):ragFile?join(rag.directory,ragFile.stored_name):join(config.dataDir,'notification-attachments',notificationFile!.stored_name);reply.header('Content-Type',file.mime).header('Content-Length',String(file.size)).header('Content-Disposition',`attachment; filename*=UTF-8''${encodeURIComponent(file.name)}`);return reply.send(createReadStream(path));});
